<script lang="ts">
import{tick}from"svelte";import{page}from"$app/state";import{movies}from"../../../shared/catalog";type Sort="relevance"|"title"|"year";let query=$state("");let status=$state("all");let sort=$state<Sort>("relevance");let filter:HTMLDialogElement;let started=0;let latency=$state("—");let results=$derived.by(()=>{const term=query.trim().toLocaleLowerCase("es");const current=status==="all"?(page.url.searchParams.get("estado")==="pendientes"?"Pendiente":page.url.searchParams.get("estado")==="historial"?"Vista":"all"):status;const list=movies.filter(m=>(!term||m.title.toLocaleLowerCase("es").includes(term)||m.genre.toLocaleLowerCase("es").includes(term)||String(m.year).includes(term))&&(current==="all"||m.status===current));if(sort==="title")list.sort((a,b)=>a.title.localeCompare(b.title,"es"));if(sort==="year")list.sort((a,b)=>b.year-a.year);return list;});
async function search(event:Event){started=performance.now();query=(event.currentTarget as HTMLInputElement).value;await tick();requestAnimationFrame(()=>latency=(performance.now()-started).toFixed(1)+" ms");}
</script>
<svelte:head><title>Descubrir · Prisma muestra</title></svelte:head>
<main class="app"><header class="top"><div><div class="kicker">MUESTRA EXPERIMENTAL</div><h1>Descubrir</h1></div><small>Datos ficticios</small></header><div class="toolbar" role="search"><label class="sr-only" for="q">Buscar películas por título, género o año</label><input id="q" type="search" placeholder="Buscar películas…" bind:value={query} oninput={search}><button onclick={()=>filter.showModal()}>Filtros</button><button onclick={()=>window.dispatchEvent(new Event("prisma:settings"))}>Ajustes</button></div><div class="results"><span aria-live="polite">{results.length} resultados</span><span>Orden: {sort==="relevance"?"Original":sort==="title"?"Título":"Año"}</span></div><div class="feed" aria-label="Feed de películas">{#each results as movie (movie.id)}<a href={"/pelicula/"+movie.id} class="poster" style:--n={movie.seed} aria-label={movie.title+", "+movie.year+", "+movie.genre}><b aria-hidden="true">{movie.title.split(" ").slice(0,2).map(s=>s[0]).join("")}</b><span class="pin">{movie.status}</span></a>{/each}</div><div class="stats">Catálogo sintético: 240 registros · Búsqueda hasta siguiente fotograma: {latency}</div></main>
<dialog class="dialog" bind:this={filter} aria-labelledby="filter-title"><h2 id="filter-title">Filtros y orden</h2><label>Estado<select bind:value={status}><option value="all">Todas</option><option value="Vista">Vista</option><option value="Pendiente">Pendiente</option></select></label><label>Orden<select bind:value={sort}><option value="relevance">Original</option><option value="title">Título A–Z</option><option value="year">Año reciente</option></select></label><div class="row"><button class="btn" onclick={()=>{status="all";sort="relevance"}}>Restablecer</button><button class="btn primary" onclick={()=>filter.close()}>Aplicar</button></div></dialog>